#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct node
{
    int size;
    int start;
    int end;
    int status;
    struct node *next;
};

struct node *head = NULL;

void insert(int size)
{
    struct node *temp = (struct node *)malloc(sizeof(struct node));
    temp->size = size;
    temp->start = 0;
    temp->end = size - 1;
    temp->status = 0;
    temp->next = NULL;

    if (head == NULL)
    {
        head = temp;
    }
    else
    {
        struct node *p = head;
        while (p->next != NULL)
        {
            p = p->next;
        }
        p->next = temp;
    }
}

void display()
{
    struct node *p = head;
    while (p != NULL)
    {
        printf("%d\t%d\t%d\t%d\n", p->size, p->start, p->end, p->status);
        p = p->next;
    }
}

void best_fit(int size)
{
    struct node *p = head;
    int min = 9999;
    struct node *temp = NULL;
    while (p != NULL)
    {
        if (p->status == 0 && p->size >= size)
        {
            if (p->size < min)
            {
                min = p->size;
                temp = p;
            }
        }
        p = p->next;
    }
    if (temp != NULL)
    {
        temp->status = 1;
        printf("Allocated memory of size %d at %d\n", size, temp->start);
    }
    else
    {
        printf("No memory available\n");
    }
}

int main()
{
    int n, size;
    printf("Enter the number of memory blocks: ");
    scanf("%d", &n);
    printf("Enter the size of each block: ");
    for (int i = 0; i < n; i++)
    {
        scanf("%d", &size);
        insert(size);
    }
    printf("Enter the size of the process: ");
    scanf("%d", &size);
    best_fit(size);
    display();
    return 0;
}
